$q=$db->prepare("SELECT t.*,h.primary_identifier horse,tr.primary_identifier trailer,d.full_name driver,d.phone driver_phone,requester.full_name requester,reviewer.full_name reviewer FROM fleet_trips t JOIN assets h ON h.id=t.horse_asset_id LEFT JOIN assets tr ON tr.id=t.trailer_asset_id JOIN drivers d ON d.id=t.driver_id JOIN users requester ON requester.id=t.requested_by LEFT JOIN users reviewer ON reviewer.id=t.decided_by WHERE t.id=? AND t.status IN ('APPROVED','IN_PROGRESS','COMPLETED')");
$q->execute([$id]);$t=$q->fetch();
