$brandLogoPath='C:/xampp/secure/fleet/waybill-brand.jpg';$logoBytes='';$logoInfo=is_file($brandLogoPath)?@getimagesize($brandLogoPath):false;if(is_array($logoInfo)&&($logoInfo['mime']??'')==='image/jpeg'){$candidate=@file_get_contents($brandLogoPath);if(is_string($candidate))$logoBytes=$candidate;}

function waybill_text(string $value):string{$value=iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',$value)?:$value;return str_replace(['\\','(',')',"\r","\n"],['\\\\','\\(','\\)',' ',' '],$value);}
function wb_color(string $hex):string{$hex=ltrim($hex,'#');$rgb=array_map(static fn($n)=>hexdec($n)/255,str_split($hex,2));return implode(' ',array_map(static fn($n)=>rtrim(rtrim(number_format($n,3,'.',''),'0'),'.'),$rgb));}
function wb_rect(string &$c,float $x,float $top,float $w,float $h,string $fill,?string $stroke=null):void{$y=842-$top-$h;$c.="q ".wb_color($fill)." rg ".($stroke?wb_color($stroke)." RG 0.8 w ":'').sprintf('%.2f %.2f %.2f %.2f re ', $x,$y,$w,$h).($stroke?'B':'f')." Q\n";}
function wb_line(string &$c,float $x1,float $top1,float $x2,float $top2,string $color='#DCE5EF',float $width=0.8):void{$c.='q '.wb_color($color)." RG {$width} w ".sprintf('%.2f %.2f m %.2f %.2f l S Q', $x1,842-$top1,$x2,842-$top2)."\n";}
function wb_text(string &$c,float $x,float $top,string $text,float $size=10,string $font='F1',string $color='#263A52'):void{if(trim($text)==='')return;$baseline=842-$top-$size;$c.='q '.wb_color($color)." rg BT /{$font} {$size} Tf 1 0 0 1 ".sprintf('%.2f %.2f',$x,$baseline).' Tm ('.waybill_text($text).") Tj ET Q\n";}
function wb_wrap(string $text,int $width,int $maxLines=3):array{$text=trim(preg_replace('/\\s+/u',' ',$text)??$text);if($text==='')return ['—'];$text=iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',$text)?:$text;$lines=explode("\n",wordwrap($text,$width,"\n",true));if(count($lines)>$maxLines){$lines=array_slice($lines,0,$maxLines);$lines[$maxLines-1]=rtrim(substr($lines[$maxLines-1],0,max(0,$width-3))).'...';}return $lines;}
function wb_label_value(string &$c,float $x,float $top,string $label,string $value,int $width=34,int $maxLines=2,float $size=10):void{wb_text($c,$x,$top,$label,7.5,'F2','#6D8098');foreach(wb_wrap($value,$width,$maxLines) as $i=>$line)wb_text($c,$x,$top+14+($i*13),$line,$size,'F2','#203650');}

