wb_text($content,42,128,'TRIP REFERENCE',7.5,'F2','#71849B');wb_text($content,42,143,(string)$t['trip_number'],17,'F2','#142B45');wb_rect($content,438,130,115,28,$t['status']==='COMPLETED'?'#E7F5EE':'#EAF1FC');wb_text($content,451,138,$status,9,'F2',$t['status']==='COMPLETED'?'#18744D':'#285FAE');
$cards=[['REQUESTED',date('d M Y, H:i',strtotime((string)$t['requested_at']))],['APPROVED / REVIEWED',$t['decided_at']?date('d M Y, H:i',strtotime((string)$t['decided_at'])):'Not recorded'],['DOCUMENT ISSUED',$now]];
foreach($cards as $i=>$card){$x=42+$i*174;wb_rect($content,$x,177,163,48,'#F3F6FA','#E1E8F0');wb_text($content,$x+12,186,$card[0],7,'F2','#72859C');wb_text($content,$x+12,201,$card[1],9,'F2','#263A52');}
// Route block
wb_rect($content,42,238,511,88,'#EEF4FD','#D7E4F6');wb_text($content,58,250,'ROUTE / MOVEMENT',7.5,'F2','#5E7591');wb_text($content,58,271,'ORIGIN',7,'F2','#71849B');$origin=wb_wrap((string)$t['pickup_location'],31,2);foreach($origin as $i=>$line)wb_text($content,58,285+$i*13,$line,11,'F2','#203650');wb_rect($content,272,276,54,24,'#FFFFFF','#D7E4F6');wb_text($content,284,282,'TO',9,'F2','#3978D5');wb_text($content,350,271,'DESTINATION',7,'F2','#71849B');$destination=wb_wrap((string)$t['destination'],30,2);foreach($destination as $i=>$line)wb_text($content,350,285+$i*13,$line,11,'F2','#203650');
