wb_rect($content,304,340,249,110,'#FFFFFF','#E1E8F0');wb_text($content,318,352,'SCHEDULE & DISPATCH',7.5,'F2','#5E7591');wb_label_value($content,318,371,'PLANNED DEPARTURE',date('d M Y, H:i',strtotime((string)$t['scheduled_departure'])),31,1,9);wb_label_value($content,438,371,'EXPECTED RETURN',$t['expected_return']?date('d M Y, H:i',strtotime((string)$t['expected_return'])):'Not recorded',25,1,9);wb_label_value($content,318,412,'ODOMETER OUT',(string)($t['odometer_start']??'Not recorded'),31,1,9);wb_label_value($content,438,412,'ODOMETER IN',(string)($t['odometer_end']??'Not recorded'),25,1,9);
// Equipment and driver
